def selection_sort(xs):
    xs = list(xs)
    n = len(xs)
    for i in range(n):
        m = i
        for j in range(i + 1, n):
            if xs[j] < xs[m]:
                m = j
        xs[i], xs[m] = xs[m], xs[i]
    return xs
```

